export async function readStoredRecords(file) {
  let text
  try {
    text = await fs.readFile(file, 'utf8')
  } catch (error) {
    if (error && error.code === 'ENOENT') return []
    throw error
  }
  if (text.trim() === '') return []
  const records = JSON.parse(text)
  if (!Array.isArray(records)) throw new Error('用量数据文件的顶层必须是数组')
