      "content": "window.__ModuleLoader__.load({\n  id: \"@feiyang666/dsh-usage-plugin\",\n  factory: (require) => {\n    var module = { exports: {} };\n    var exports = module.exports;\n    Object.defineProperty(exports, Symbol.toStringTag, { value: \"Module\" });\n    var React = require(\"react\");\n    var el = React.createElement;\n    // react-dom 是平台种子模块：用于把弹窗 Portal 到 document.body，\n    // 避免对话树祖先的 transform/contain 破坏 position:fixed（弹窗不可见）。\n    var ReactDOM = null;\n    try { ReactDOM = require(\"react-dom\"); } catch (e2) {}\n    // 隐藏弹窗卡片滚动条外观（仍可滚轮滚动），并在小屏下贴近视口\n    try {\n      if (typeof document !== \"undefined\" && document.head && !document.getElementById(\"dsh-usage-tok-style\")) {\n        var __tokStyle = document.createElement(\"style\");\n        __tokStyle.id = \"dsh-usage-tok-style\";\n        __tokStyle.textContent = \"[data-dsh-usage-tok]{scrollbar-width:none;-ms-overflow-style:none}[data-dsh-usage-tok]::-webkit-scrollbar{width:0;height:0;display:none}\";\n        document.head.appendChild(__tokStyle);\n      }\n    } catch (e3) {}\n\n    // ── i18n: zh keys → en dictionary (community addition) ──\n    var __T_EN = {\"本期无消耗（所有用量为 0）\":\"No usage this turn (all zeros)\",\"按模型\":\"By model\",\"…及另外 \":\"…plus \",\" 个模型（完整列表见「用量与消耗」页签）\":\" more models (full list in the Usage & Cost tab)\",\"对话累计\":\"Conversation total\",\"本轮明细\":\"This turn\",\"本轮 token\":\"Turn tokens\",\"本轮消耗\":\"Turn cost\",\"本轮缓存命中率\":\"Turn hit rate\",\"本轮耗时\":\"Turn duration\",\"本轮无记录\":\"No records this turn\",\"工具调用（内部）\":\"Tool calls (internal)\",\" 条内部调用\":\" internal calls\",\"展开\":\"Expand\",\"收起\":\"Collapse\",\"详细记录请在「用量与消耗」页签查看\":\"Full details are in the Usage & Cost tab\",\"获取中…\":\"Loading…\",\"总 token\":\"Total tokens\",\"Token 明细\":\"Token details\",\"本次输出\":\"This output\",\"总消耗\":\"Total cost\",\"耗时\":\"Run time\",\"缓存命中率\":\"Cache hit rate\",\"关闭\":\"Close\",\"V4.1 调价\":\"V4.1 price change\",\" 2026-09-10 12:00（北京时间）起 deepseek-flash 按新版峰谷价计费（deepseek-v4-pro 不变）\":\" from 2026-09-10 12:00 Beijing time deepseek-flash uses the new peak/off-peak prices (deepseek-v4-pro unchanged)\",\"官方来源与价格依据\":\"Official sources & price references\",\"价格由 DeepSeek 官方公布，本插件只做本地计算、不修改也不代理官方价格；点下面的链接可直接核对官方原文。\":\"Prices are published by DeepSeek; this plugin only computes locally and neither changes nor proxies official pricing. Use the links below to verify against the official source.\",\"DeepSeek 官方价格页（模型与价格、峰谷时段定义）\":\"DeepSeek official pricing page (models, prices, peak/off-peak hours)\",\"DeepSeek V4.1 Flash 发布公告\":\"DeepSeek V4.1 Flash announcement\",\"DeepSeek 开放平台用量页（官方账单，用于对账）\":\"DeepSeek platform usage page (official billing, for reconciliation)\",\"DeepSeek 官方 API 文档\":\"DeepSeek official API documentation\",\"DeepSeek Harness 官方仓库\":\"DeepSeek Harness official repository\",\"为什么显示这个价格？\":\"Why is this the price shown?\",\"① 官方价格表按生效时间分段：2026-08-17 00:00 起为第一版峰谷价；2026-09-10 12:00（北京时间）起为 DeepSeek V4.1 Flash 调价后的新版（deepseek-flash 单价下调，deepseek-v4-pro 不变）。每次调用按其发生时刻对应的版本计费，历史金额不会因后续调价而改变。\":\"① The official price table is split by effective date: the first peak/off-peak version applies from 2026-08-17 00:00, and the post-V4.1-Flash version from 2026-09-10 12:00 Beijing time (deepseek-flash prices are lowered; deepseek-v4-pro is unchanged). Every call is billed with the version in force at its own time, so past amounts never change when prices are adjusted later.\",\"② 模型档位按官方新命名归并：旧名 deepseek-v4-flash、deepseek-v4-flash-vision-exp 仍可调用（官方已路由到 DeepSeek-V4.1-Flash 并按 Flash 单价计费），计费时与 deepseek-flash 合并为同一档位。\":\"② Model tiers follow the new official naming: the legacy ids deepseek-v4-flash and deepseek-v4-flash-vision-exp stay callable (DeepSeek routes them to DeepSeek-V4.1-Flash and bills them at the Flash price) and are merged into the same deepseek-flash tier for billing.\",\"③ 峰谷规则：工作日 9:00–12:00、14:00–18:00（北京时间）为高峰，其余时间（含周末全天）为空闲；空闲价 = 高峰价的一半。\":\"③ Peak/off-peak rule: weekdays 9:00–12:00 and 14:00–18:00 Beijing time are peak; all other times (including the whole weekend) are off-peak; the off-peak price is half the peak price.\",\"④ 只有能与记录中 provider / model 可靠匹配的价格才参与计费，其余按 ¥0 统计（避免用相近模型的价格误算）。\":\"④ Only prices that reliably match the recorded provider / model are billed; everything else counts as ¥0, so a similar model name never causes a wrong estimate.\",\"⑤ 本插件按官方公布价格在本地计算，结果仅供参考，最终以 DeepSeek 官方账单为准；产品价格可能变动，请以官方价格页为准。\":\"⑤ This plugin computes locally from published prices; the result is for reference only and the official DeepSeek bill prevails. Prices may change, so always check the official pricing page.\",\"建议：若新模型（如 deepseek-flash）的消耗显示为 ¥0，通常是本插件版本过旧——请升级到 1.17.0 或更高版本。\":\"Tip: if a new model (such as deepseek-flash) shows ¥0 cost, this plugin is usually out of date — please upgrade to 1.17.0 or later.\",\"DeepSeek V4.1 Flash 调价将于 \":\"The DeepSeek V4.1 Flash price change takes effect on \",\"（北京时间）生效：deepseek-flash 改用新版峰谷价（空闲 缓存命中 0.02 / 输入 1 / 输出 4 元，高峰为其两倍），deepseek-v4-pro 价格不变。\":\" (Beijing time): deepseek-flash switches to the new peak/off-peak prices (off-peak cache hit 0.02 / input 1 / output 4 CNY; peak is twice that), while deepseek-v4-pro stays unchanged.\",\"DeepSeek V4.1 Flash 调价已生效（自 \":\"The DeepSeek V4.1 Flash price change is in effect (since \",\" 起）：deepseek-flash 按新版峰谷价计费，deepseek-v4-pro 价格不变。\":\"): deepseek-flash is billed at the new peak/off-peak prices; deepseek-v4-pro is unchanged.\",\"峰谷价表按生效时间分段：2026-08-17 00:00 起为第一版峰谷价；2026-09-10 12:00 起为 DeepSeek V4.1 Flash 调价后的新版（deepseek-flash 空闲价下调为 缓存命中 0.02 / 输入 1 / 输出 4 元，高峰为其两倍；deepseek-v4-pro 价格不变）。上方「峰谷价」展示的是当前生效的一版，历史调用始终按其发生时刻对应的版本计费。\":\"The peak/off-peak tables are split by effective date: the first version applies from 2026-08-17 00:00, and the post-V4.1-Flash version applies from 2026-09-10 12:00 (deepseek-flash off-peak prices are lowered to cache hit 0.02 / input 1 / output 4 CNY, with peak at twice that; deepseek-v4-pro is unchanged). The Peak/Off-peak tab shows the currently effective version; past calls are always billed with the version in force at their own time.\",\"旧模型名 deepseek-v4-flash 与 deepseek-v4-flash-vision-exp 仍可调用（官方已将其路由到 DeepSeek-V4.1-Flash、按 Flash 单价计费），在本价格表中与 deepseek-flash 合并为同一档位。\":\"The legacy model ids deepseek-v4-flash and deepseek-v4-flash-vision-exp remain callable (they are routed to DeepSeek-V4.1-Flash and billed at the Flash price) and are merged into the deepseek-flash row in this table.\",\"无 Token 数据\":\"No token data\",\"当前 · \":\"Current · \",\"工作日高峰时段\":\"Weekday peak hours\",\"工作日空闲时段\":\"Weekday off-peak hours\",\"周末高峰时段\":\"Weekend peak hours\",\"周末空闲时段\":\"Weekend off-peak hours\",\"周一至周五 9:00–12:00、14:00–18:00\":\"Mon–Fri 9:00–12:00 & 14:00–18:00\",\"工作日其余时间\":\"Other weekday hours\",\"周末（周六、周日）全天按空闲价计费\":\"All weekend (Sat & Sun) billed at the off-peak rate\",\"2026-08-23 前仍按原规则分峰谷\":\"Before 2026-08-23 the old peak/valley split still applies\",\"高峰 / 空闲时段说明\":\"Peak / off-peak hours\",\"工作日高峰\":\"Weekday peak\",\"空闲时段\":\"Off-peak hours\",\" 周一至周五 9:00–12:00、14:00–18:00\":\" Mon–Fri 9:00–12:00 & 14:00–18:00\",\" 工作日其余时间，以及周末（周六、周日）全天（自 2026-08-23 起；此前仍按原规则分峰谷）\":\" Weekday off-peak hours, plus all weekend (Sat & Sun) since 2026-08-23 (before that, the old peak/valley split still applies)\",\"工作日高峰 9:00–12:00、14:00–18:00 · 周末全天空闲价\":\"Weekday peak 9:00–12:00 & 14:00–18:00 · all-weekend off-peak rate\",\"\\n调用 \":\"\\ncalls \",\"）\\n输入·未命中 \":\")\\ninput·miss \",\"\\n高峰消耗 \":\"\\npeak cost \",\"\\n无记录\":\"\\nno records\",\"自动模式：按调用时间自动选择计费档位——新价格表生效前的调用按基础价（旧价格表），生效后的调用按峰谷价（工作日高峰时段 9:00–12:00、14:00–18:00 用高峰价，其余时间——含周末全天——用空闲价）。当前显示：\":\"Auto mode: the billing tier is chosen automatically by call time — calls made before the new price schedule took effect are billed at base (old) prices; calls after it use peak/valley prices (weekday peak hours 9:00–12:00 & 14:00–18:00 at the peak price, all other times — including all weekend — at the off-peak price). Currently shown:\",\"单位：元 / 百万 tokens。工作日高峰时段（北京时间 9:00–12:00、14:00–18:00）用高峰价，其余时间用空闲价（空闲价 = 高峰价的一半）；自 2026-08-23 起周末（周六、周日）全天按空闲价计费，新规则生效前仍按原规则。概览、用量日历、缓存命中列表中的消耗均已按高峰 / 空闲分列统计。\":\"Unit: CNY per million tokens. Weekday peak hours (Beijing time 9:00–12:00 & 14:00–18:00) use the peak price; all other times use the off-peak price (off-peak = half of peak). Since 2026-08-23, weekends (Sat & Sun) are billed at the off-peak rate all day; calls before the new rule still follow the old split. Costs in Overview, Usage Calendar and the Cache Hit List are split into peak / off-peak accordingly.\",\"未知模型\":\"Unknown model\",\"未知服务商\":\"Unknown provider\",\"完成\":\"Done\",\"工具调用\":\"Tool call\",\"超长\":\"Overlong\",\"错误\":\"Error\",\"已中断\":\"Interrupted\",\"超时\":\"Timeout\",\"中断\":\"Interrupted\",\" · 中断 \":\" · interrupted \",\"（未计费）\":\" (not billed)\",\"本地统计与官方后台的差异\":\"Local stats vs official console\",\"本面板统计的是插件在本地捕获的模型调用（按官方价格与峰谷时段计费）。与官方后台（platform.deepseek.com 用量页）相比，金额可能更低，常见原因：\":\"This panel shows calls captured locally by the plugin (billed at official prices with peak/off-peak rates). Compared with the official console (platform.deepseek.com usage page), the amount may be lower — common reasons:\",\"① 中断/出错/超时的调用：官方仍按实际 token 计费，插件无法获取其用量，按 0 记录（明细中标「中断」）；\":\"① Interrupted/failed/timed-out calls: the console still bills their actual tokens, but the plugin cannot obtain their usage, so they are recorded as 0 (marked \\\"Interrupted\\\" in details);\",\"② 账号下其他 API Key（如其它应用/脚本）的调用不经过 DeepSeek Harness，官方统计包含它们，本插件不包含；\":\"② Calls from other API keys on your account (e.g. other apps/scripts) do not pass through DeepSeek Harness — the console includes them, this plugin does not;\",\"③ 如需精确对账，可在官方用量页导出月度账单 CSV 与本插件对比。\":\"③ For exact reconciliation, export the monthly billing CSV from the official usage page and compare it with this plugin.\",\"当前记录中有 \":\"Current records include \",\" 次中断调用（未计费）——对应官方后台已计费的部分。\":\" interrupted call(s) (not billed) — corresponding to the part already billed by the official console.\",\"范围内调用\":\"Calls in range\",\"范围内消耗\":\"Cost in range\",\"该范围内暂无记录。\":\"No records in this range.\",\"自动（生效前基础价 · 生效后峰谷价）\":\"Auto (base price before effective date · peak/valley after)\",\"基础价格\":\"Base price\",\"峰谷价格\":\"Peak/valley price\",\"自动\":\"Auto\",\"canvas 2d 不可用\":\"canvas 2D unavailable\",\"用量与消耗报告\":\"Usage & Cost Report\",\"生成时间 \":\"Generated \",\"（北京） · 共 \":\" (Beijing) · total \",\" 条调用 · 缓存命中率 \":\" calls · cache-hit rate \",\" · 高峰价消耗 \":\" · peak-rate cost \",\" · 空闲价消耗 \":\" · off-peak cost \",\" · 合计 \":\" · total \",\" · 报告仅含最近 \":\" · report limited to the latest \",\" 条\":\" records\",\"调用次数\":\"Calls\",\"输入 · 未命中\":\"Input · miss\",\"输入 · 缓存命中\":\"Input · cache hit\",\"输出\":\"Output\",\"高峰消耗\":\"Peak cost\",\"空闲消耗\":\"Off-peak cost\",\"总消耗 (峰谷价)\":\"Total cost (peak/valley)\",\"缓存命中列表（共 \":\"Cache hit list (\",\" 条）\":\" records)\",\"时间(北京)\":\"Time (Beijing)\",\"模型\":\"Model\",\"输入·未命中\":\"Input·miss\",\"缓存命中\":\"Cache hit\",\"缓存写入\":\"Cache write\",\"推理\":\"Reasoning\",\"命中率\":\"Hit rate\",\"时段\":\"Period\",\"结束\":\"End\",\"消耗(峰谷)\":\"Cost (peak/valley)\",\"峰\":\"Peak\",\"谷\":\"Valley\",\"消耗表（按模型 · 峰谷价 · 高峰/空闲分列）\":\"Cost table (by model · peak/valley prices)\",\"调用\":\"Calls\",\"总消耗\":\"Total cost\",\"合计\":\"Total\",\"消耗表（按 API 服务商 × 模型 · 峰谷价）\":\"Cost table (by API provider × model · peak/valley)\",\"API 服务商 / 模型\":\"API provider / model\",\" 个模型）\":\" models)\",\"总费用合计\":\"Total cost overall\",\"计价按请求的 API 服务商分别应用已核验价格；DigitalOcean 美元价按 USD/CNY 汇率折算；无法可靠映射的第三方价格按 ¥0。\":\"Billing applies verified prices per requesting API provider; DigitalOcean USD prices are converted at the USD/CNY rate; third-party prices that cannot be mapped reliably are counted as ¥0.\",\" 个服务商\":\" providers\",\"今天\":\"Today\",\"近7天\":\"Last 7 days\",\"近30天\":\"Last 30 days\",\"全部\":\"All\",\"自定义区间：\":\"Custom range:\",\"至\":\"to\",\"清除筛选\":\"Clear filters\",\"当前范围：共 \":\"Current range: \",\"（全部记录）\":\"(all records)\",\" · 总消耗 \":\" · total cost \",\"高峰 \":\"Peak